import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def _w(u, v, d):
    """Safe edge weight: missing/None cost gets a large penalty."""
    c = d.get("cost")
    return c if c is not None else 1e9


def _emit(bc, dst, path, G, nparts):
    """Record one path for every partition of dst."""
    for i in range(len(path) - 1):
        s, t = path[i], path[i + 1]
        for j in range(nparts):
            bc.append_dst_partition_path(dst, j, [s, t, G[s][t]])


def _tree_cost(paths, h):
    """Cost of the union of edges (edge reuse = free)."""
    used, total = set(), 0.0
    for p in paths:
        for i in range(len(p) - 1):
            e = (p[i], p[i + 1])
            if e not in used:
                used.add(e)
                total += _w(e[0], e[1], h[e[0]][e[1]])
    return total


def search_algorithm(src, dsts, G, num_partitions):
    """Greedy marginal-cost Steiner broadcast with Steiner-MST fallback.

    Process destinations cheapest-shortest-path-first; for each, examine
    candidate simple paths and pick the one minimizing the cost of *new*
    edges only (edges already on the shared trunk are free). Compare with
    a Kou-Markowsky Steiner tree over the metric closure and emit whichever
    yields a cheaper union of edges. Unreachable dsts are skipped gracefully.
    """
    if src not in G:
        return BroadCastTopology(src, dsts, num_partitions)
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    bc = BroadCastTopology(src, dsts, num_partitions)

    valid = [d for d in dict.fromkeys(dsts) if d in h]
    try:
        dist, spaths = nx.single_source_dijkstra(h, src, weight=_w)
    except (nx.NetworkXNoPath, nx.NodeNotFound):
        dist, spaths = {}, {}

    # Strategy A: greedy marginal-cost routing onto a shared trunk
    greedy, used = {}, set()
    for dst in sorted(valid, key=lambda d: dist.get(d, float("inf"))):
        best_path, best_marg = spaths.get(dst), float("inf")
        try:
            gen = nx.shortest_simple_paths(h, src, dst, weight=_w)
            budget = dist.get(dst, float("inf")) * 2 + 1e9
            for count, p in enumerate(gen):
                if count >= 60 or _tree_cost([p], h) > budget:
                    break
                marg = sum(_w(p[i], p[i + 1], h[p[i]][p[i + 1]])
                           for i in range(len(p) - 1)
                           if (p[i], p[i + 1]) not in used)
                if marg < best_marg:
                    best_path, best_marg = p, marg
                if marg == 0:
                    break
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            pass
        if best_path is None:
            continue
        greedy[dst] = best_path
        for i in range(len(best_path) - 1):
            used.add((best_path[i], best_path[i + 1]))

    # Strategy B: Kou-Markowsky Steiner tree on the metric closure
    steiner = {}
    try:
        terminals = [src] + valid
        dp = dict(nx.all_pairs_dijkstra(h, weight=_w))
        closure = nx.Graph()
        for i, a in enumerate(terminals):
            for b in terminals[i + 1:]:
                if b in dp[a][0]:
                    closure.add_edge(a, b, weight=dp[a][0][b])
        shared = nx.DiGraph()
        for a, b in nx.minimum_spanning_tree(closure, weight="weight").edges():
            pa, pb = dp[a][1].get(b), dp[b][1].get(a)
            if pa is not None and (pb is None or dp[a][0][b] <= dp[b][0][a]):
                path = pa
            elif pb is not None:
                path = pb
            else:
                continue
            for i in range(len(path) - 1):
                s, t = path[i], path[i + 1]
                shared.add_edge(s, t, cost=_w(s, t, h[s][t]))
        for dst in valid:
            if dst in shared:
                try:
                    steiner[dst] = nx.dijkstra_path(shared, src, dst, weight=_w)
                except (nx.NetworkXNoPath, nx.NodeNotFound):
                    pass
        if set(steiner) != set(valid):
            steiner = {}
    except (nx.NetworkXNoPath, nx.NodeNotFound, KeyError):
        steiner = {}

    # pick the cheaper complete strategy (greedy always complete)
    cand = [greedy] + ([steiner] if steiner and set(steiner) == set(greedy) else [])
    chosen = min(cand, key=lambda ps: _tree_cost(list(ps.values()), h))

    for dst in valid:
        path = chosen.get(dst) or spaths.get(dst)
        if path:
            _emit(bc, dst, path, G, bc.num_partitions)

    return bc


